package com.agenda.clinica.service;
import com.agenda.clinica.dto.request.CitaRequest; import com.agenda.clinica.dto.response.CitaResponse; import com.agenda.clinica.entity.*; import com.agenda.clinica.exception.ReglaNegocioException; import com.agenda.clinica.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class CitaService { private final CitaRepository citas; private final PacienteRepository pacientes; private final MedicoRepository medicos; public CitaService(CitaRepository c,PacienteRepository p,MedicoRepository m){citas=c;pacientes=p;medicos=m;}
 @Transactional public CitaResponse crear(CitaRequest r){ if(!r.fin().isAfter(r.inicio())) throw new ReglaNegocioException("La hora final debe ser posterior a la hora inicial."); if(r.inicio().isBefore(LocalDateTime.now())) throw new ReglaNegocioException("No se pueden reservar citas en el pasado."); Medico medico=medicos.bloquear(r.medicoId()).orElseThrow(()->new NoSuchElementException()); if(!medico.isActivo()) throw new ReglaNegocioException("El médico no está disponible para nuevas citas."); Paciente p=(r.documento()!=null&&!r.documento().isBlank()?pacientes.findByDocumento(r.documento()):pacientes.findByTelefono(r.telefono().trim())).orElseGet(()->{Paciente n=new Paciente();n.setNombre(r.nombrePaciente().trim());n.setTelefono(r.telefono().trim());n.setCorreo(r.correo());n.setDocumento(r.documento());return pacientes.save(n);}); pacientes.bloquear(p.getId()); if(citas.existeCruce(r.inicio(),r.fin(),medico.getId(),p.getId())) throw new ReglaNegocioException("El paciente o el médico ya tiene una cita que se cruza con ese horario."); Cita c=new Cita();c.setPaciente(p);c.setMedico(medico);c.setInicio(r.inicio());c.setFin(r.fin());c.setMotivo(r.motivo());return CitaResponse.from(citas.save(c)); }
 public List<CitaResponse> agenda(LocalDate desde,LocalDate hasta){return citas.agenda(desde.atStartOfDay(),hasta.plusDays(1).atStartOfDay()).stream().map(CitaResponse::from).toList();}
 @Transactional public CitaResponse cambiarEstado(Long id,String estado){Cita c=citas.findById(id).orElseThrow(); if(!List.of("PROGRAMADA","CONFIRMADA","COMPLETADA","CANCELADA","NO_ASISTIO").contains(estado)) throw new ReglaNegocioException("Estado de cita no válido."); if(c.getEstado().equals("CANCELADA")) throw new ReglaNegocioException("Una cita cancelada no puede modificarse."); c.setEstado(estado);return CitaResponse.from(c);}
}
